data: {"id":"chatcmpl-20261007053108931863909c955d568Zoj13ZDO","created":1791351069,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_ff57d22ca36d427eb25c1122","index":0,"type":"function","function":{"name":"write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Simulate a lock-contention / deadlock scenario in SQLite.\\n\\nTwo threads, two connections, opposite update orders:\\n\\n    Thread A: update account 1 -> sleep -> update account 2\\n    Thread B: update account 2 -> sleep -> update account 1\\n\\nEach thread runs inside an explicit DEFERRED transaction. A small read of\\nboth rows after BEGIN primes a SHARED lock on each connection; with both\\nconnections holding SHARED locks, the first UPDATE upgrades to RESERVED,\\nand the crisscross (each thread needing a lock the other holds) is what\\nmakes SQLite return SQLITE_BUSY, i.e. \\\"database is locked\\\".\\n\\nThe sleep between updates widens the race window so the interleaving that\\nproduces the deadlock happens much more often.\\n\\\"\\\"\\\"\\n\\nimport sqlite3\\nimport threading\\nimport time\\n\\nDB_PATH = \\\"migration.db\\\"\\nAMOUNT = 10\\nSLEEP_SECONDS = 0.1  # sleep between the two updates; grows the race window\\nBUSY_TIMEOUT = 5.0  # seconds each connection waits before giving up\\n\\nstart_barrier = threading.Barrier(2)\\n\\n\\ndef worker(name: str, first_id: int, second_id: int) -> None:\\n    \\\"\\\"\\\"Run one side of the crisscross: update first_id, sleep, second_id.\\\"\\\"\\\"\\n    conn = sqlite3.connect(DB_PATH, timeout=BUSY_TIMEOUT, isolation_level=None)\\n    try:\\n        start_barrier.wait()  # release both threads at the same instant\\n\\n        conn.execute(\\\"BEGIN\\\")  # DEFERRED: no locks taken yet\\n        # Read-only peek primes a SHARED lock on this connection.\\n        conn.execute(\\\"SELECT balance FROM accounts WHERE id = ?\\\", (first_id,)).fetchone()\\n        print(f\\\"[{name}] BEGIN; updating account {first_id}\\\")\\n\\n        try:\\n            conn.execute(\\n                \\\"UPDATE accounts SET balance = balance + ? WHERE id = ?\\\",\\n                (AMOUNT, first_id),\\n            )\\n            print(f\\\"[{name}] updated account {first_id}; sleeping {SLEEP_SECONDS}s\\\")\\n        except sqlite3.OperationalError as exc:\\n            print(f\\\"[{name}] FAILED on first update (account {first_id}): {exc}\\\")\\n            conn.execute(\\\"ROLLBACK\\\")\\n            print(f\\\"[{name}] rolled back\\\")\\n            return\\n\\n        time.sleep(SLEEP_SECONDS)\\n\\n        print(f\\\"[{name}] updating account {second_id}\\\")\\n        try:\\n            conn.execute(\\n                \\\"UPDATE accounts SET balance = balance + ? WHERE id = ?\\\",\\n                (AMOUNT, second_id),\\n            )\\n            print(f\\\"[{name}] updated account {second_id}\\\")\\n        except sqlite3.OperationalError as exc:\\n            print(f\\\"[{name}] FAILED on second update (account {second_id}): {exc}\\\")\\n            conn.execute(\\\"ROLLBACK\\\")\\n            print(f\\\"[{name}] rolled back\\\")\\n            return\\n\\n        try:\\n            conn.execute(\\\"COMMIT\\\")\\n            print(f\\\"[{name}] committed\\\")\\n        except sqlite3.OperationalError as exc:\\n            print(f\\\"[{name}] FAILED on commit: {exc}\\\")\\n            conn.execute(\\\"ROLLBACK\\\")\\n            print(f\\\"[{name}] rolled back\\\")\\n    finally:\\n        conn.close()\\n\\n\\ndef main() -> None:\\n    thread_a = threading.Thread(target=worker, args=(\\\"A\\\", 1, 2), name=\\\"A\\\")\\n    thread_b = threading.Thread(target=worker, args=(\\\"B\\\", 2, 1), name=\\\"B\\\")\\n\\n    thread_a.start()\\n    thread_b.start()\\n    thread_a.join()\\n    thread_b.join()\\n\\n    conn = sqlite3.connect(DB_PATH)\\n    rows = conn.execute(\\\"SELECT id, balance FROM accounts ORDER BY id\\\").fetchall()\\n    conn.close()\\n    print(\\\"Final balances:\\\", \\\", \\\".join(f\\\"account {r[0]}={r[1]}\\\" for r in rows))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"file_path\":\"/home/agent/workspace/deadlock_sim.py\",\"intent\":\"Write deadlock simulation script\"}"}}]}}]}

