      "start_line": 1,
      "limit": 200
    },
    {
      "tool": "agentgrep",
      "intent": "Find configuration usage",
      "query": "Config",
      "path": "src",
      "glob": "**/*.rs",
      "max_files": 20,
      "max_regions": 20
    }
  ]
}

