data: {"id":"chatcmpl-20261007053450156955657c955d568NrU87vxf","created":1791351290,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_1f2d6be0baf44ed7a7eeac5e","index":0,"type":"function","function":{"name":"write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Simulate lock contention in SQLite, resolved with transaction retries.\\n\\nTwo threads, two connections, opposite update orders:\\n\\n    Thread A: update account 1 -> sleep -> update account 2\\n    Thread B: update account 2 -> sleep -> update account 1\\n\\nEach thread runs inside an explicit DEFERRED transaction. A small read\\nafter BEGIN primes a SHARED lock; when both connections then try to\\nupgrade to a write lock in a crisscross, SQLite returns SQLITE_BUSY\\n(\\\"database is locked\\\") to the loser.\\n\\nRetry mechanism: on a busy/locked error the transaction is rolled back\\nand retried, up to 3 attempts, with a short delay between attempts. The\\nloser's retry starts after the winner has committed, so both\\ntransactions eventually complete successfully.\\n\\\"\\\"\\\"\\n\\nimport sqlite3\\nimport threading\\nimport time\\n\\nDB_PATH = \\\"migration.db\\\"\\nAMOUNT = 10\\nSLEEP_SECONDS = 0.1  # sleep between the two updates; grows the race window\\nBUSY_TIMEOUT = 5.0  # seconds each connection waits before giving up\\nMAX_ATTEMPTS = 3  # total attempts per transaction (1 initial + 2 retries)\\nRETRY_DELAY = 0.2  # seconds to wait before retrying a busy transaction\\n\\nstart_barrier = threading.Barrier(2)\\n\\n\\ndef is_busy_error(exc: sqlite3.OperationalError) -> bool:\\n    \\\"\\\"\\\"True when the error is SQLITE_BUSY / database is locked.\\\"\\\"\\\"\\n    msg = str(exc).lower()\\n    return \\\"database is locked\\\" in msg or \\\"database table is locked\\\" in msg\\n\\n\\ndef safe_rollback(conn: sqlite3.Connection) -> None:\\n    \\\"\\\"\\\"Roll back, tolerating the case where no transaction is active.\\\"\\\"\\\"\\n    try:\\n        conn.execute(\\\"ROLLBACK\\\")\\n    except sqlite3.OperationalError:\\n        pass\\n\\n\\ndef run_transaction(name: str, conn: sqlite3.Connection, first_id: int, second_id: int) -> bool:\\n    \\\"\\\"\\\"Run one transaction attempt. Returns True on commit, False on failure.\\\"\\\"\\\"\\n    conn.execute(\\\"BEGIN\\\")  # DEFERRED: no locks taken yet\\n    # Read-only peek primes a SHARED lock on this connection.\\n    conn.execute(\\\"SELECT balance FROM accounts WHERE id = ?\\\", (first_id,)).fetchone()\\n    print(f\\\"[{name}] BEGIN; updating account {first_id}\\\")\\n\\n    conn.execute(\\n        \\\"UPDATE accounts SET balance = balance + ? WHERE id = ?\\\",\\n        (AMOUNT, first_id),\\n    )\\n    print(f\\\"[{name}] updated account {first_id}; sleeping {SLEEP_SECONDS}s\\\")\\n\\n    time.sleep(SLEEP_SECONDS)\\n\\n    print(f\\\"[{name}] updating account {second_id}\\\")\\n    conn.execute(\\n        \\\"UPDATE accounts SET balance = balance + ? WHERE id = ?\\\",\\n        (AMOUNT, second_id),\\n    )\\n    print(f\\\"[{name}] updated account {second_id}\\\")\\n\\n    conn.execute(\\\"COMMIT\\\")\\n    return True\\n\\n\\ndef worker(name: str, first_id: int, second_id: int) -> None:\\n    \\\"\\\"\\\"Run one side of the crisscross with up to MAX_ATTEMPTS tries.\\\"\\\"\\\"\\n    conn = sqlite3.connect(DB_PATH, timeout=BUSY_TIMEOUT, isolation_level=None)\\n    try:\\n        for attempt in range(1, MAX_ATTEMPTS + 1):\\n            if attempt == 1:\\n                start_barrier.wait()  # release both threads at the same instant\\n\\n            try:\\n                run_transaction(name, conn, first_id, second_id)\\n                print(f\\\"[{name}] committed on attempt {attempt}/{MAX_ATTEMPTS}\\\")\\n                return\\n            except sqlite3.OperationalError as exc:\\n                safe_rollback(conn)\\n                if is_busy_error(exc) and attempt < MAX_ATTEMPTS:\\n                    print(\\n                        f\\\"[{name}] attempt {attempt} hit '{exc}'; \\\"\\n                        f\\\"rolled back, retrying in {RETRY_DELAY}s\\\"\\n                    )\\n                    time.sleep(RETRY_DELAY)\\n                    continue\\n                print(f\\\"[{name}] FAILED permanently after {attempt} attempt(s): {exc}\\\")\\n                return\\n    finally:\\n        conn.close()\\n\\n\\ndef main() -> None:\\n    thread_a = threading.Thread(target=worker, args=(\\\"A\\\", 1, 2), name=\\\"A\\\")\\n    thread_b = threading.Thread(target=worker, args=(\\\"B\\\", 2, 1), name=\\\"B\\\")\\n\\n    thread_a.start()\\n    thread_b.start()\\n    thread_a.join()\\n    thread_b.join()\\n\\n    conn = sqlite3.connect(DB_PATH)\\n    rows = conn.execute(\\\"SELECT id, balance FROM accounts ORDER BY id\\\").fetchall()\\n    conn.close()\\n    print(\\\"Final balances:\\\", \\\", \\\".join(f\\\"account {r[0]}={r[1]}\\\" for r in rows))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"file_path\":\"/home/agent/workspace/deadlock_sim.py\",\"intent\":\"Add retry mechanism to deadlock simulation\"}"}}]}}]}

